const code1 = "from fastapi import FastAPI, Request, WebSocket, WebSocketDisconnect\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.templating import Jinja2Templates\nimport json\nimport os\nimport openai\nfrom dotenv import load_dotenv, find_dotenv\n\nmessages = [{'role': 'system', 'content': 'You are a helpful assistant'}]\n\n# Get the API key from environment variables\n_ = load_dotenv(find_dotenv())  # read local .env file\nopenai.api_key = os.environ[\"OPENAI_API_KEY\"]\n\n# Create a OpenAI ChatGPT completion function\ndef get_chat_response():\n    global messages\n    response = openai.ChatCompletion.create(\n        model=\"gpt-3.5-turbo\",\n        messages=messages,\n        temperature=0.7\n    )\n    messages.append({'role': 'assistant', 'content': response.choices[0].message['content']})\n\napp = FastAPI(debug=True)\n\n# Set static file location\napp.mount(\"/assets\", StaticFiles(directory=\"app/dist/assets\", html=True), name=\"static\")\n\n# Setup Jinja2 templates to serve index.html\ntemplates = Jinja2Templates(directory=\"app/dist\")\n\n# Serve index.html template from the root path\n@app.get(\"/\")\nasync def root(request: Request):\n    return templates.TemplateResponse(\"index.html\", {\"request\": request})\n\n# Create a websocket connection\n@app.websocket(\"/ws\")\nasync def websocket_endpoint(websocket: WebSocket):\n    await websocket.accept()\n    try:\n        while True:\n            data = await websocket.receive_text()\n            message_data = json.loads(data)\n            print(message_data)\n            if message_data['type'] == 'get_messages':\n                return_message = {'type': 'message_update', 'content': messages[1:]}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n            if message_data['type'] == 'new_message':\n                new_message = message_data['content']\n                messages.append({'role': 'user', 'content': new_message})\n                get_chat_response()\n                return_message = {'type': 'message_update', 'content': messages[1:]}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n            if message_data['type'] == 'clear_messages':\n                messages.clear()\n                messages.append({'role': 'system', 'content': 'You are a helpful assistant'})\n                return_message = {'type': 'message_update', 'content': messages[1:]}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n    except WebSocketDisconnect:\n        print(\"Client disconnected\")\n\nif __name__ == \"__main__\":\n    import uvicorn\n    uvicorn.run(app, host=\"0.0.0.0\", port=8000)\n";
const code2 = "async sendMessage(event) {\n    // If the user presses enter, prevent the default form action\n    if (event) {\n        event.preventDefault();\n    }\n\n    if (this.messageContent.trim() !== '') {\n\n        const newMessage = {\n            type: 'new_message',\n            content: this.messageContent,\n        };\n        this.sendSocketMessage(newMessage);\n        this.messageContent = '';\n    }\n}\n";
const code3 = ".chat-bubble {\n  display: flex;\n  align-items: center;\n  flex-direction: row;\n  margin-bottom: 10px;\n}\n\n.chat-bubble.assistant {\n  flex-direction: row-reverse;\n}\n\n.chat-bubble-avatar {\n  flex-shrink: 0;\n  background-color: #e1e1e1;\n  border-radius: 50%;\n  color: #000;\n  font-weight: bold;\n  height: 40px;\n  width: 40px;\n  line-height: 40px;\n  margin-right: 10px;\n  text-align: center;\n  margin: 0px 10px;\n  box-shadow: 0 0 5px rgba(0, 0, 0, 0.2);\n}\n\n.chat-bubble-content {\n  border-radius: 10px;\n  padding: 10px;\n  box-shadow: 0 0 5px rgba(0, 0, 0, 0.2);\n  max-width: 80%;\n}\n\n.user .chat-bubble-content {\n  background-color: #f6db99;\n}\n\n.assistant .chat-bubble-content {\n  background-color: #f6f8d0;\n}\n";
const code4 = "from fastapi import FastAPI, Request, WebSocket, WebSocketDisconnect\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.templating import Jinja2Templates\nimport json\nimport os\nimport openai\nfrom dotenv import load_dotenv, find_dotenv\nfrom pymongo import MongoClient\n\n# Connect to MongoDB\nclient = MongoClient('mongodb://127.0.0.1:27017/')\ndb = client['vue-chatbot']\nmessages_collection = db['messages']\nmessages_collection.delete_many({}) # Clear the messages collection\nmessages_collection.insert_one({'role': 'system', 'content': 'You are a helpful assistant'}) # Add a system message\n\n# Get the API key from environment variables\n_ = load_dotenv(find_dotenv())  # read local .env file\nopenai.api_key = os.environ[\"OPENAI_API_KEY\"]\n\n# Create a OpenAI ChatGPT completion function\ndef get_chat_response():\n    messages = get_messages()\n    response = openai.ChatCompletion.create(\n        model=\"gpt-3.5-turbo\",\n        messages=messages,\n        temperature=0.7\n    )\n    messages_collection.insert_one({'role': 'assistant', 'content': response.choices[0].message['content']})\n\ndef get_messages():\n    messages = list(messages_collection.find({}))\n    for message in messages:\n        message.pop('_id')\n    return messages\n\napp = FastAPI(debug=True)\n\n# Set static file location\napp.mount(\"/assets\", StaticFiles(directory=\"app/dist/assets\", html=True), name=\"static\")\n\n# Setup Jinja2 templates to serve index.html\ntemplates = Jinja2Templates(directory=\"app/dist\")\n\n# Serve index.html template from the root path\n@app.get(\"/\")\nasync def root(request: Request):\n    return templates.TemplateResponse(\"index.html\", {\"request\": request})\n\n# Create a websocket connection\n@app.websocket(\"/ws\")\nasync def websocket_endpoint(websocket: WebSocket):\n    await websocket.accept()\n    try:\n        while True:\n            data = await websocket.receive_text()\n            message_data = json.loads(data)\n            if message_data['type'] == 'get_messages':\n                messages = get_messages()\n                await websocket.send_text(json.dumps({'type': 'message_update', 'content': messages[1:]}))\n\n            if message_data['type'] == 'new_message':\n                new_message = message_data['content']\n                messages_collection.insert_one({'role': 'user', 'content': new_message})\n                messages = get_messages()\n                await websocket.send_text(json.dumps({'type': 'message_update', 'content': messages[1:]}))\n                get_chat_response()\n                messages = get_messages()\n                await websocket.send_text(json.dumps({'type': 'message_update', 'content': messages[1:]}))\n\n            if message_data['type'] == 'clear_messages':\n                messages_collection.delete_many({})\n                messages_collection.insert_one({'role': 'system', 'content': 'You are a helpful assistant'})\n                messages = get_messages()\n                await websocket.send_text(json.dumps({'type': 'message_update', 'content': messages[1:]}))\n\n    except WebSocketDisconnect:\n        print(\"Client disconnected\")\n\nif __name__ == \"__main__\":\n    import uvicorn\n    uvicorn.run(app, host=\"0.0.0.0\", port=8000)\n";
const code5 = "version: \"3\"\n\nservices:\n  webapp:\n    build:\n      context: .\n      dockerfile: Dockerfile\n    ports:\n      - \"8000:8000\"\n    depends_on:\n      - mongodb\n    environment:\n      - MONGO_URI=mongodb://mongodb:27017\n\n  mongodb:\n    build:\n      context: .\n      dockerfile: Dockerfile.mongo\n    ports:\n      - \"27017:27017\"\n";
const code6 = "FROM python:3.11\n\n# Set the working directory to /app\nWORKDIR /app\n\n# Install any needed packages specified in requirements.txt\nCOPY requirements.txt .\nRUN pip install -r requirements.txt\n\n# Copy the current directory contents into the container at /app\nCOPY . .\n\n# Make port 8000 available to the world outside this container\nEXPOSE 8000\n\n# Run main.py when the container launches\nCMD [\"python\", \"main.py\"]\n";
const code7 = "FROM mongo:latest\n\n# Run mongod when the container launches\nCMD [\"mongod\", \"--bind_ip_all\"]\n";
const code8 = "from fastapi import FastAPI, Request, WebSocket, WebSocketDisconnect\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.templating import Jinja2Templates\nimport json\nimport os\nimport openai\nfrom dotenv import load_dotenv, find_dotenv\nfrom pymongo import MongoClient\n\n# read local .env file\n_ = load_dotenv(find_dotenv())\n\n# Connect to MongoDB\nuri = os.environ[\"MONGO_URI\"]\nclient = MongoClient(uri)\ndb = client['vue-chatbot']\nmessages_collection = db['messages']\nmessages_collection.delete_many({}) # Clear the messages collection\nmessages_collection.insert_one({'role': 'system', 'content': 'You are a helpful assistant'}) # Add a system message\n\n### Rest of your code here ###\n";
</script>

<template>
  <p>Building your own custom web app can feel daunting, especially if you are not a web developer. There are plenty of nice visual design tools out there, but you lose granular control if you do not write the code yourself. As someone who is not a web developer, I found Vue.js to be a great framework to start with: it is easy to learn and has thorough documentation and community support. In this series, I will show you how to build a chatbot using Vue.js and connect it to a back-end API that calls GPT-3.5. At the end, we will store the messages in a MongoDB database so that we can reuse them later.</p>
  <p>If you want to jump straight to the finished product, you can find the repository here.</p>
  <GithubRepoCard repo="lancewilhelm/vue-chatbot" />
  <hr />
  <p>If you missed the earlier parts, start with <RouterLink to="/blog/vue-chatbot1">Part 1</RouterLink> and then <RouterLink to="/blog/vue-chatbot2">Part 2</RouterLink> before jumping into this part.</p>
  <hr />
  <ProseHeading id="what-is-gpt-35" :level="2">What is GPT-3.5?</ProseHeading>
  <p>GPT-3.5 is a Large Language Model (LLM) from OpenAI that generates natural language text from a prompt. For example, if we give it the prompt “Hello, my name is Lance and I am a Ph.D. Student. I like to”, it predicts likely ways to finish the sentence. Here we will use the instruction-tuned version called ChatGPT, which was fine-tuned on chatbot conversations and fits our use case well.</p>
  <ProseHeading id="talking-to-gpt-35" :level="2">Talking to GPT-3.5</ProseHeading>
  <p>Most of our work now happens on the back-end, where we will call OpenAI's API to generate replies from the messages that we send. First, get an API key by signing up for an account on OpenAI's <a href="https://openai.com" target="_blank" rel="noopener noreferrer">website</a>. New users get $5 of free credits, which is plenty for testing.</p>
  <p>Before creating a key, add a file named <code>.env</code> at the root of your project to store the key as an environment variable. That keeps your API key out of source control (<strong>as long as <code>.env</code> is listed in your <code>.gitignore</code></strong>). Inside <code>.env</code>, add the following line:</p>
  <CodeBlock language="bash" filename=".env" :code="code0" />
  <p>Now create an API key on <a href="https://platform.openai.com/account/api-keys" target="_blank" rel="noopener noreferrer">OpenAI's API keys page</a> and paste it into <code>.env</code> in place of <code>YOUR_API_KEY_HERE</code>. With that set up, we can update <code>main.py</code> to call the OpenAI API.</p>
  <p>Replace the contents of <code>main.py</code> with the following:</p>
  <CodeBlock language="python" filename="main.py" :code="code1" />
  <p>There is more going on at the top than before, so let's walk through it. We import <code>openai</code> to call the API, along with <code>os</code> and <code>dotenv</code> to load <code>OPENAI_API_KEY</code> from <code>.env</code> into <code>openai.api_key</code>. Next, we define <code>get_chat_response()</code> to request a reply from OpenAI, and we call it inside the websocket endpoint whenever a new user message arrives. We also seed the conversation with a system prompt so that the model knows how to respond.</p>
  <p>Rebuild the front-end with <code>npm run build</code> inside <code>app/</code> and run <code>python main.py</code> from the root directory. You can now chat with an actual AI bot!</p>
  <BlogImage eager image-path="/img/vue-chatbot/chatbot6.png" alt="Chatbot conversation with the language model" caption="The chatbot is alive!" width="600px" />
  <p>Right now, the chatbot has a bug: it does not display the user's message until the model finishes replying. We will fix that later by sending the message list back from the websocket endpoint as soon as the user submits a message. There are also a couple of UI quirks to clean up first.</p>
  <ProseHeading id="fixing-some-bugs" :level="2">Fixing some bugs</ProseHeading>
  <p>First, you may have noticed that pressing Enter sends the message and also inserts a blank line into the text box. Update <code>sendMessage()</code> in <code>InputRow.vue</code> as shown below:</p>
  <CodeBlock language="javascript" filename="inputRow.vue" :code="code2" />
  <p>We now inspect the keyboard event when a message is sent. If an event is present, we call <code>preventDefault()</code> so that pressing Enter does not add a newline to the text box.</p>
  <p>Next, let's fix those squished avatar circles by updating the CSS in <code>ChatBubble.vue</code>:</p>
  <CodeBlock language="css" filename="ChatBubble.vue" :code="code3" />
  <p>Setting <code>flex-shrink: 0</code> on the avatar keeps it from shrinking on narrow screens while keeping its width and height fixed at 40px. Setting <code>max-width: 80%</code> on the message bubble keeps long replies from stretching across the entire screen.</p>
  <BlogImage image-path="/img/vue-chatbot/chatbot7.png" alt="Updated chatbot interface and conversation" caption="Looking much better" width="600px" />
  <p>Now it is time for MongoDB!</p>
  <ProseHeading id="what-is-mongodb" :level="2">What is MongoDB?</ProseHeading>
  <p>MongoDB is a NoSQL database that stores data in JSON-like documents. It works well for data without a fixed schema and is easy to get started with. We will use MongoDB to save the messages that our chatbot receives so that we can analyze conversations or use them for training later.</p>
  <ProseHeading id="setting-up-mongodb" :level="2">Setting up MongoDB</ProseHeading>
  <p>To run MongoDB with the current prototype, install it locally using the <a href="https://docs.mongodb.com/manual/installation/" target="_blank" rel="noopener noreferrer">official installation guide</a> and start the server in the background by running <code>mongod</code> in your terminal.</p>
  <p>If you would rather skip installing MongoDB directly, wait for the Docker section later in this post. We will use Docker Compose to run MongoDB inside a container instead.</p>
  <ProseHeading id="connecting-to-mongodb" :level="2">Connecting to MongoDB</ProseHeading>
  <p>With MongoDB running, install <code>pymongo</code> (<code>pip install pymongo</code>) so that our back-end can connect to it, then replace <code>main.py</code> with the following:</p>
  <CodeBlock language="python" filename="main.py" :code="code4" />
  <p>First, we import <code>MongoClient</code>, connect to the local database, and create a <code>messages</code> collection. On startup, we clear that collection so that we start fresh (we could skip that step later if we want to keep chat history across restarts) and insert the initial system message.</p>
  <p>We also update <code>get_chat_response()</code> to read from and write to MongoDB, and add a helper function, <code>get_messages()</code>, that retrieves the stored messages. The websocket endpoint now uses MongoDB to read, insert, and clear messages, and sends an immediate update after saving the user's message so that it appears right away.</p>
  <p>With that in place, our messages are now stored in MongoDB! Start the app with <code>python main.py</code>. To inspect the database directly, run <code>mongosh</code> in your terminal to open the MongoDB shell: run <code>show dbs</code> to confirm that <code>vue-chatbot</code> is listed, <code>use vue-chatbot</code> to select it, <code>show collections</code> to see <code>messages</code>, and <code>db.messages.find()</code> to view the stored messages.</p>
  <BlogImage image-path="/img/vue-chatbot/chatbot8.png" alt="MongoDB running for the chatbot" caption="MongoDB running!" width="600px" />
  <ProseHeading id="dockerizing-our-application" :level="2">Dockerizing our application</ProseHeading>
  <p>Now that the app works end to end, we can package it with Docker so that it is easy to deploy to a server or share across Windows, macOS, and Linux without installing every dependency manually. We will use Docker Compose because it lets us run both our web app container and the MongoDB container together.</p>
  <p>You will need Docker and Docker Compose installed to follow along. You can find installation instructions for Docker <a href="https://docs.docker.com/get-docker/" target="_blank" rel="noopener noreferrer">in the Docker docs</a> and for Docker Compose in <a href="https://docs.docker.com/compose/install/" target="_blank" rel="noopener noreferrer">the Compose installation guide</a>.</p>
  <p>First, create a file named <code>docker-compose.yml</code> in the root directory with the following configuration:</p>
  <CodeBlock language="yaml" filename="docker-compose.yml" :code="code5" />
  <p>This file tells Docker Compose how to build and run both containers. The <code>webapp</code> service builds from <code>Dockerfile</code>, exposes port 8000, and depends on the <code>mongodb</code> service, which builds from <code>Dockerfile.mongo</code> and exposes port 27017. It also sets the <code>MONGO_URI</code> environment variable to <code>mongodb://mongodb:27017</code> so that our web app can reach the database container.</p>
  <p>Next, create <code>Dockerfile</code> in the root directory with the following contents:</p>
  <CodeBlock language="dockerfile" filename="Dockerfile" :code="code6" />
  <p>This Dockerfile starts from Python 3.11, sets the working directory to <code>/app</code>, and installs the packages listed in <code>requirements.txt</code> (which combines all of the packages that we installed with <code>pip</code>; see the GitHub repo for the full file). It then copies the project files into <code>/app</code>, exposes port 8000, and launches <code>main.py</code>.</p>
  <p>Next, create <code>Dockerfile.mongo</code> in the root directory:</p>
  <CodeBlock language="dockerfile" filename="Dockerfile.mongo" :code="code7" />
  <p>This file is much simpler: it starts from the latest MongoDB image and runs <code>mongod</code> when the container starts.</p>
  <p>Finally, update the top of <code>main.py</code> so that it reads the <code>MONGO_URI</code> environment variable instead of a hard-coded localhost address:</p>
  <CodeBlock language="python" filename="main.py" :code="code8" />
  <p>Now we can build and run everything with Docker Compose. First, make sure that you have built the latest front-end by running <code>npm run build</code> inside <code>app/</code>. Then run <code>docker-compose up --build</code> from the project root. Once both containers start, the app is available at <code>localhost:8000</code> and MongoDB at <code>localhost:27017</code>. Run <code>docker-compose down</code> to stop the containers.</p>
  <BlogImage image-path="/img/vue-chatbot/chatbot9.png" alt="Dockerized chatbot running" caption="Dockerized and ready to go!" width="600px" />
  <ProseHeading id="conclusion" :level="2">Conclusion</ProseHeading>
  <p>It was a long journey: we built a Vue.js front-end in part 1, connected it to a FastAPI back-end in part 2, and wired up GPT-3.5, MongoDB, and Docker in part 3. I hope that you learned something along the way and feel ready to build a chatbot of your own!</p>
</template>
